import { authenticateHeader } from './src/auth/session_guard.mjs';
import assert from 'node:assert';

const secret = 'SECRET_test123';
const validPayload = Buffer.from(JSON.stringify({ sub: 'user_42', exp: Date.now() + 60000 })).toString('base64url');
const expiredPayload = Buffer.from(JSON.stringify({ sub: 'user_42', exp: Date.now() - 60000 })).toString('base64url');

assert.deepStrictEqual(authenticateHeader(\`Bearer \${validPayload}.\${secret}\`, secret), { valid: true, userId: 'user_42' });
assert.strictEqual(authenticateHeader(\`Bearer \${expiredPayload}.\${secret}\`, secret).valid, false);
assert.strictEqual(authenticateHeader(\`Bearer \${validPayload}.WRONG\`, secret).valid, false);
assert.strictEqual(authenticateHeader('InvalidHeader', secret).valid, false);
assert.strictEqual(authenticateHeader(null, secret).valid, false);
console.log('All tests passed');
